def scd_customer(c,cdc):
    base=c[['customer_id','customer_name','customer_segment','industry','city','state','country','region','signup_date','credit_limit','payment_terms','risk_tier','is_active']].copy(); base['effective_start_date']=base.signup_date.fillna('1900-01-01'); base['record_source']='customer_master'
    upd=cdc.merge(c[['customer_id','customer_name','industry','city','state','country','region','signup_date','credit_limit','is_active']], on='customer_id', how='inner').rename(columns={'new_customer_segment':'customer_segment','new_risk_tier':'risk_tier','new_payment_terms':'payment_terms','effective_date':'effective_start_date','change_reason':'record_source'})[base.columns]
    s=pd.concat([base,upd], ignore_index=True); s['_dt']=pd.to_datetime(s.effective_start_date,errors='coerce'); s=s.sort_values(['customer_id','_dt']); s['effective_end_date']=s.groupby('customer_id')['_dt'].shift(-1).dt.date.astype('string').fillna('9999-12-31'); s['is_current']=s.effective_end_date.eq('9999-12-31'); s['customer_sk']=[stable_hash(a,b,c,d,e) for a,b,c,d,e in zip(s.customer_id,s.effective_start_date,s.customer_segment,s.risk_tier,s.payment_terms)]; return s.drop(columns=['_dt'])[['customer_sk']+[x for x in s.columns if x not in ['customer_sk','_dt']]]
def scd_product(p,cdc):
    base=p.copy(); base['effective_start_date']=base.launch_date.fillna('1900-01-01'); base['record_source']='product_master'
    upd=cdc.merge(p.drop(columns=['list_price','product_status']), on='product_id', how='inner'); upd['list_price']=upd.new_list_price; upd['product_status']=upd.new_product_status; upd['effective_start_date']=upd.effective_date; upd['record_source']=upd.change_reason; upd=upd[base.columns]
    s=pd.concat([base,upd], ignore_index=True); s['_dt']=pd.to_datetime(s.effective_start_date,errors='coerce'); s=s.sort_values(['product_id','_dt']); s['effective_end_date']=s.groupby('product_id')['_dt'].shift(-1).dt.date.astype('string').fillna('9999-12-31'); s['is_current']=s.effective_end_date.eq('9999-12-31'); s['product_sk']=[stable_hash(a,b,c,d) for a,b,c,d in zip(s.product_id,s.effective_start_date,s.list_price,s.product_status)]; return s.drop(columns=['_dt'])
def build_gold(s):
    c=s['customers']; sup=s['suppliers']; p=s['products']; w=s['warehouses']; car=s['carriers']; fx=s['fx_rates']; o=s['sales_orders']; l=s['sales_order_lines']; po=s['purchase_orders']; pol=s['purchase_order_lines']; sh=s['shipments']; rec=s['receipts']; rcl=s['receipt_lines']; inv=s['inventory_snapshots']; adj=s['inventory_adjustments']; ret=s['returns']; invoices=s['invoices']; pay=s['payments']
    for name,df in {'dim_customer_scd2':scd_customer(c,s['customer_cdc']),'dim_product_scd2':scd_product(p,s['product_cdc']),'dim_supplier':sup,'dim_warehouse':w,'dim_carrier':car}.items(): save(df,GOLD/f'{name}.csv')
    orders=o[o.customer_id.isin(c.customer_id)&o.ship_from_warehouse_id.isin(w.warehouse_id)&o.order_date.notna()].copy()
    lines=l[l.order_id.isin(orders.order_id)&l.product_id.isin(p.product_id)&l.valid_quantity&l.valid_unit_price&l.valid_discount].copy(); lines['gross_sales']=lines.ordered_qty*lines.unit_price; lines['discount_amount']=lines.gross_sales*(lines.discount_pct/100); lines['net_sales']=lines.gross_sales-lines.discount_amount
    sales=lines.merge(orders[['order_id','customer_id','order_date','promised_delivery_date','sales_channel','order_status','order_priority','currency','ship_from_warehouse_id']],on='order_id').merge(p[['product_id','category','subcategory','brand','supplier_id','standard_cost','unit_weight_lbs']],on='product_id',how='left')
    sales=sales.merge(fx[['rate_date','currency','usd_rate']], left_on=['order_date','currency'], right_on=['rate_date','currency'], how='left'); missing_fx=sales[sales.usd_rate.isna()]; q('sales_lines_missing_fx_rate',missing_fx,'Sales line currency/date missing FX rate'); sales['usd_rate']=sales.usd_rate.fillna(1); sales['net_sales_usd']=sales.net_sales*sales.usd_rate; sales['gross_sales_usd']=sales.gross_sales*sales.usd_rate; sales['discount_amount_usd']=sales.discount_amount*sales.usd_rate; sales['estimated_cost_usd']=sales.ordered_qty*sales.standard_cost.fillna(0)*sales.usd_rate; sales['gross_margin_usd']=sales.net_sales_usd-sales.estimated_cost_usd; sales['is_large_order_line']=sales.net_sales_usd>=CONFIG['large_order_threshold_usd']; save(sales,GOLD/'fact_sales_order_lines.csv')
    order_fact=sales.groupby('order_id',as_index=False).agg(order_line_count=('order_line_id','count'),total_order_qty=('ordered_qty','sum'),gross_sales_usd=('gross_sales_usd','sum'),net_sales_usd=('net_sales_usd','sum'),discount_amount_usd=('discount_amount_usd','sum'),gross_margin_usd=('gross_margin_usd','sum')).merge(orders,on='order_id',how='left'); save(order_fact,GOLD/'fact_sales_orders.csv')
    ship=sh[sh.order_id.isin(orders.order_id)&sh.carrier_id.isin(car.carrier_id)].merge(orders[['order_id','customer_id','order_date','promised_delivery_date']],on='order_id',how='left'); save(ship,GOLD/'fact_shipments.csv')
    valid_po=po[po.supplier_id.isin(sup.supplier_id)&po.warehouse_id.isin(w.warehouse_id)].copy(); valid_pol=pol[pol.po_id.isin(valid_po.po_id)&pol.product_id.isin(p.product_id)&pol.valid_quantity&pol.valid_unit_cost].copy(); proc=valid_pol.merge(valid_po[['po_id','supplier_id','warehouse_id','po_date','expected_receipt_date','currency','po_status']],on='po_id'); proc['po_line_amount']=proc.ordered_qty*proc.unit_cost; proc=proc.merge(fx[['rate_date','currency','usd_rate']],left_on=['po_date','currency'],right_on=['rate_date','currency'],how='left'); proc['usd_rate']=proc.usd_rate.fillna(1); proc['po_line_amount_usd']=proc.po_line_amount*proc.usd_rate; save(proc,GOLD/'fact_purchase_order_lines.csv')
    receipt=rcl[rcl.po_line_id.isin(valid_pol.po_line_id)&rcl.valid_received_qty].merge(rec[['receipt_id','po_id','warehouse_id','receipt_date','receipt_status','inspection_status']],on='receipt_id',how='left').merge(valid_pol[['po_line_id','po_id','ordered_qty','unit_cost']],on=['po_line_id','po_id'],how='left'); receipt['fill_rate']=safe_divide(receipt.received_qty,receipt.ordered_qty); receipt['rejected_rate']=safe_divide(receipt.rejected_qty,receipt.received_qty); save(receipt,GOLD/'fact_receipts.csv')
    latest=inv.sort_values('snapshot_date').groupby(['warehouse_id','product_id'],as_index=False).tail(1); latest=latest[latest.warehouse_id.isin(w.warehouse_id)&latest.product_id.isin(p.product_id)]; latest['stockout_flag']=latest.available_qty<=0; latest['below_reorder_point_flag']=latest.available_qty<=latest.reorder_point; latest['overstock_flag']=latest.available_qty>latest.reorder_point*4; save(latest,GOLD/'inventory_position_current.csv')
    adjf=adj[adj.warehouse_id.isin(w.warehouse_id)&adj.product_id.isin(p.product_id)&adj.adjustment_qty.notna()]; save(adjf,GOLD/'fact_inventory_adjustments.csv')
    valid_ret=ret[ret.order_id.isin(orders.order_id)&ret.order_line_id.isin(l.order_line_id)]; save(valid_ret,GOLD/'fact_returns.csv')
    valid_inv=invoices[invoices.order_id.isin(orders.order_id)&invoices.invoice_amount.notna()].copy(); valid_pay=pay[pay.invoice_id.isin(valid_inv.invoice_id)&pay.payment_amount.notna()].copy(); paid=valid_pay[valid_pay.payment_status.eq('Posted')].groupby('invoice_id',as_index=False).agg(total_paid=('payment_amount','sum'),last_payment_date=('payment_date','max'),payment_count=('payment_id','count')); ar=valid_inv.merge(paid,on='invoice_id',how='left').fillna({'total_paid':0,'payment_count':0}); ar['open_amount']=ar.invoice_amount-ar.total_paid; ar['paid_in_full_flag']=ar.open_amount.abs()<=.01; ar['days_past_due']=(pd.Timestamp('2026-06-01')-pd.to_datetime(ar.due_date,errors='coerce')).dt.days; ar['is_past_due']=(ar.open_amount>0)&(ar.days_past_due>0); save(ar,GOLD/'accounts_receivable_aging.csv')
    save(sales.groupby(['order_date','sales_channel'],as_index=False).agg(order_count=('order_id','nunique'),line_count=('order_line_id','count'),units_ordered=('ordered_qty','sum'),net_sales_usd=('net_sales_usd','sum'),gross_margin_usd=('gross_margin_usd','sum')),GOLD/'mart_daily_sales.csv')
    prod=sales.groupby(['product_id','category','subcategory','brand'],as_index=False).agg(units_ordered=('ordered_qty','sum'),net_sales_usd=('net_sales_usd','sum'),gross_margin_usd=('gross_margin_usd','sum'),order_count=('order_id','nunique')); rprod=valid_ret.groupby('product_id',as_index=False).agg(returned_qty=('return_qty','sum'),refund_amount=('refund_amount','sum'),return_count=('return_id','count')); prod=prod.merge(rprod,on='product_id',how='left').fillna({'returned_qty':0,'refund_amount':0,'return_count':0}); prod['return_rate']=safe_divide(prod.returned_qty,prod.units_ordered); save(prod.sort_values('net_sales_usd',ascending=False),GOLD/'mart_product_performance.csv')
    supp=proc.groupby('supplier_id',as_index=False).agg(po_count=('po_id','nunique'),ordered_units=('ordered_qty','sum'),po_spend_usd=('po_line_amount_usd','sum')).merge(sup[['supplier_id','supplier_name','supplier_tier','country','quality_score','on_time_delivery_rate']],on='supplier_id',how='left'); sr=receipt.merge(valid_po[['po_id','supplier_id','expected_receipt_date']],on='po_id',how='left'); sr['receipt_late_flag']=pd.to_datetime(sr.receipt_date,errors='coerce')>pd.to_datetime(sr.expected_receipt_date,errors='coerce'); srs=sr.groupby('supplier_id',as_index=False).agg(received_units=('received_qty','sum'),avg_fill_rate=('fill_rate','mean'),late_receipt_count=('receipt_late_flag','sum'),receipt_count=('receipt_id','nunique')); supp=supp.merge(srs,on='supplier_id',how='left').fillna({'received_units':0,'avg_fill_rate':0,'late_receipt_count':0,'receipt_count':0}); supp['computed_on_time_rate']=1-safe_divide(supp.late_receipt_count,supp.receipt_count); save(supp.sort_values(['avg_fill_rate','computed_on_time_rate']),GOLD/'mart_supplier_scorecard.csv')
    wh=latest.groupby('warehouse_id',as_index=False).agg(sku_count=('product_id','nunique'),on_hand_qty=('on_hand_qty','sum'),available_qty=('available_qty','sum'),stockout_sku_count=('stockout_flag','sum'),below_reorder_sku_count=('below_reorder_point_flag','sum'),overstock_sku_count=('overstock_flag','sum')).merge(w[['warehouse_id','warehouse_name','region','capacity_units']],on='warehouse_id',how='left'); shipwh=ship.groupby('warehouse_id',as_index=False).agg(shipment_count=('shipment_id','count'),late_delivery_count=('is_late_delivery','sum'),avg_transit_days=('transit_days','mean'),shipping_cost=('shipping_cost','sum')); wh=wh.merge(shipwh,on='warehouse_id',how='left').fillna({'shipment_count':0,'late_delivery_count':0,'avg_transit_days':0,'shipping_cost':0}); wh['capacity_utilization_estimate']=safe_divide(wh.on_hand_qty,wh.capacity_units); save(wh.sort_values('stockout_sku_count',ascending=False),GOLD/'mart_warehouse_operations.csv')
    fulfill=orders[['order_id','customer_id','order_date','promised_delivery_date','order_priority','sales_channel']].merge(ship.groupby('order_id',as_index=False).agg(first_ship_ts=('ship_ts','min'),last_delivery_ts=('delivery_ts','max'),shipment_count=('shipment_id','count'),any_late_delivery=('is_late_delivery','max')),on='order_id',how='left'); fulfill['order_to_ship_days']=(pd.to_datetime(fulfill.first_ship_ts,errors='coerce')-pd.to_datetime(fulfill.order_date,errors='coerce')).dt.total_seconds()/86400; fulfill['order_to_delivery_days']=(pd.to_datetime(fulfill.last_delivery_ts,errors='coerce')-pd.to_datetime(fulfill.order_date,errors='coerce')).dt.total_seconds()/86400; fulfill['unshipped_flag']=fulfill.first_ship_ts.isna(); save(fulfill,GOLD/'mart_fulfillment_performance.csv')
    cust360=c.merge(order_fact.groupby('customer_id',as_index=False).agg(order_count=('order_id','count'),total_net_sales_usd=('net_sales_usd','sum'),total_margin_usd=('gross_margin_usd','sum')),on='customer_id',how='left').merge(valid_inv.groupby('customer_id',as_index=False).agg(invoice_count=('invoice_id','count'),invoiced_amount=('invoice_amount','sum')),on='customer_id',how='left').fillna({'order_count':0,'total_net_sales_usd':0,'total_margin_usd':0,'invoice_count':0,'invoiced_amount':0}); cust360['credit_utilization_estimate']=safe_divide(cust360.invoiced_amount,cust360.credit_limit); cust360['customer_value_tier']=pd.cut(cust360.total_net_sales_usd,bins=[-1,10000,50000,200000,float('inf')],labels=['Bronze','Silver','Gold','Platinum']).astype('string'); save(cust360.sort_values('total_net_sales_usd',ascending=False),GOLD/'mart_customer_360.csv')
    recon=order_fact[['order_id','net_sales_usd']].merge(valid_inv.groupby('order_id',as_index=False).agg(invoice_amount=('invoice_amount','sum')),on='order_id',how='left').fillna({'invoice_amount':0}); recon['difference']=recon.invoice_amount-recon.net_sales_usd; recon['reconciliation_status']=np.where(recon.difference.abs()<=1,'Matched','Mismatch'); save(recon,GOLD/'recon_sales_vs_invoices.csv')
    pr=valid_pol.groupby('po_line_id',as_index=False).agg(ordered_qty=('ordered_qty','sum')).merge(receipt.groupby('po_line_id',as_index=False).agg(received_qty=('received_qty','sum')),on='po_line_id',how='left').fillna({'received_qty':0}); pr['open_qty']=pr.ordered_qty-pr.received_qty; pr['receipt_status_computed']=np.where(pr.open_qty<=0,'Fully Received',np.where(pr.received_qty>0,'Partially Received','Open')); save(pr,GOLD/'recon_po_vs_receipts.csv')
