def main():
    ensure_dirs(BRONZE,SILVER,GOLD,QUAR,REPORT,META); raw_counts={}; silver={}
    for name,path in RAW.items():
        raw=read_csv(PROJECT_ROOT/path); raw_counts[name]=len(raw); bronze(name,raw); clean=CLEAN[name](raw); silver[name]=clean; save(clean,SILVER/f'{name}.csv')
    qs={}; c=silver
    qs['products_invalid_supplier_id']=q('products_invalid_supplier_id',c['products'][~c['products'].supplier_id.isin(c['suppliers'].supplier_id)],'Product references missing supplier')
    qs['sales_orders_invalid_customer_id']=q('sales_orders_invalid_customer_id',c['sales_orders'][~c['sales_orders'].customer_id.isin(c['customers'].customer_id)],'Sales order references missing customer')
    qs['sales_orders_invalid_warehouse_id']=q('sales_orders_invalid_warehouse_id',c['sales_orders'][~c['sales_orders'].ship_from_warehouse_id.isin(c['warehouses'].warehouse_id)],'Sales order references missing warehouse')
