    qs['purchase_orders_invalid_supplier_id']=q('purchase_orders_invalid_supplier_id',c['purchase_orders'][~c['purchase_orders'].supplier_id.isin(c['suppliers'].supplier_id)],'PO references missing supplier')
    qs['purchase_orders_invalid_warehouse_id']=q('purchase_orders_invalid_warehouse_id',c['purchase_orders'][~c['purchase_orders'].warehouse_id.isin(c['warehouses'].warehouse_id)],'PO references missing warehouse')
    qs['purchase_order_lines_invalid_po_id']=q('purchase_order_lines_invalid_po_id',c['purchase_order_lines'][~c['purchase_order_lines'].po_id.isin(c['purchase_orders'].po_id)],'PO line references missing PO')
    qs['purchase_order_lines_invalid_product_id']=q('purchase_order_lines_invalid_product_id',c['purchase_order_lines'][~c['purchase_order_lines'].product_id.isin(c['products'].product_id)],'PO line references missing product')
    qs['purchase_order_lines_bad_values']=q('purchase_order_lines_bad_values',c['purchase_order_lines'][~(c['purchase_order_lines'].valid_quantity&c['purchase_order_lines'].valid_unit_cost)],'PO line has invalid values')
