    qs['shipment_events_invalid_shipment_id']=q('shipment_events_invalid_shipment_id',c['shipment_events'][~c['shipment_events'].shipment_id.isin(c['shipments'].shipment_id)],'Event references missing shipment')
    qs['receipts_invalid_po_id']=q('receipts_invalid_po_id',c['receipts'][~c['receipts'].po_id.isin(c['purchase_orders'].po_id)],'Receipt references missing PO')
    qs['receipt_lines_invalid_receipt_id']=q('receipt_lines_invalid_receipt_id',c['receipt_lines'][~c['receipt_lines'].receipt_id.isin(c['receipts'].receipt_id)],'Receipt line references missing receipt')
    qs['receipt_lines_invalid_po_line_id']=q('receipt_lines_invalid_po_line_id',c['receipt_lines'][~c['receipt_lines'].po_line_id.isin(c['purchase_order_lines'].po_line_id)],'Receipt line references missing PO line')
    qs['receipt_lines_bad_values']=q('receipt_lines_bad_values',c['receipt_lines'][~c['receipt_lines'].valid_received_qty],'Receipt line invalid qty')
    qs['inventory_snapshots_bad_values']=q('inventory_snapshots_bad_values',c['inventory_snapshots'][~c['inventory_snapshots'].valid_inventory_qty],'Inventory bad qty')
