    for k,v in qs.items(): dq.append({'check_name':k,'table_name':k.split('_')[0],'raw_count':'','silver_count':'','issue_count':v,'severity':'warning' if v else 'pass'})
    save(pd.DataFrame(dq),REPORT/'data_quality_report.csv')
